def u64(x):
    return x & ((1<<64)-1)

def compute(n):
    rdx=u64(n*0xf4243)
    rdx=u64(rdx+7)
    rdx=u64(rdx*rdx)
    rdx=u64(rdx+8)
    rdx=u64(rdx*0xf0f0f0f0f0f0f0f1)
    rdx=u64(rdx+0x4b4b4b4b4b4b4b4b)
    return rdx
thr=0x0f0f0f0f0f0f0f0e

sol=[]
for n in range(0,200000):
    if compute(n)<=thr:
        sol.append(n)
        if len(sol)>=20:
            break
print('found',len(sol),'first:',sol[:20])
print('min rdx',min((compute(n),n) for n in range(0,200000))[:2])
